contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log1, address log2) public {
        require(log1 != address(0) && log2 != address(0));

        c.SetLogFile(log1); if (__ESBMC_reverted()) return;

        c.SetLogFile(log2); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }

    receive() external payable {}
}

