        try c.SetLogFile(log2) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetLogFile(log1) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

